import json, hashlib, re, binascii, subprocess, os, sys, zlib
from email.utils import parsedate_to_datetime
os.chdir('/app/repo.git')
inv = json.load(open('/tmp/inventory.json'))
objs = {h:(t, body.encode('latin1')) for h,(t,body) in inv['objs'].items()}
ids = inv['ids']
def full(prefix):
    c = [h for h in ids if h.startswith(prefix)]
    assert len(c) == 1, (prefix, c); return c[0]
def blob(h): assert objs[h][0]=='blob'; return objs[h][1]
def sha(t, body): return hashlib.sha1(f'{t} {len(body)}\0'.encode()+body).hexdigest()
def parse_tree(body):
    ents = []; i = 0
    while i < len(body):
        j = body.index(b'\0', i); mode, name = body[i:j].split(b' ',1); s = binascii.hexlify(body[j+1:j+21]).decode(); i = j+21
        ents.append((mode.decode(), name.decode(), s))
    return ents
def build_tree(ents):
    # git sorts entries by name, with directories as name + '/'
    def key(e): return e[1] + ('/' if e[0]=='40000' else '')
    out = b''
    for mode, name, s in sorted(ents, key=key):
        out += f'{mode} {name}\0'.encode() + binascii.unhexlify(s)
    return out
def apply_patch(pre, hunks):
    lines = pre.split(b'\n'); 
    # keep trailing: pre ends with \n => last element ''
    out = []; pos = 0  # pos index in lines (0-based)
    for (ostart, olen, nstart, nlen, body) in hunks:
        ostart0 = ostart-1 if olen>0 else ostart
        out += lines[pos:ostart0]; pos = ostart0
        for l in body:
            if l.startswith(b' '): assert lines[pos]==l[1:], (lines[pos], l); out.append(l[1:]); pos+=1
            elif l.startswith(b'-'): assert lines[pos]==l[1:], (lines[pos], l); pos+=1
            elif l.startswith(b'+'): out.append(l[1:])
            elif l == b'': pass
            else: raise Exception(l)
    out += lines[pos:]
    return b'\n'.join(out)
patches = {}
for name, b in [('0001','4691dda4f3222f39290b634d98cfd477e75d74ad'),('0002','304deb779d54ef4fc6bc2b49b72d1c7367393f4e'),('0003','cd7084c9e5db82aa880f476b018d11d852aa8f35')]:
    txt = blob(b)
    hdr, _, rest = txt.partition(b'\n---\n')
    m = re.match(rb'From ([0-9a-f]{40}) .*\nFrom: (.*)\nDate: (.*)\nSubject: \[PATCH \d/\d\] (.*?)\n(?:\n(.*))?$', hdr, re.S)
    cid, author, date, subj, body = m.groups()
    dt = parsedate_to_datetime(date.decode())
    ts = int(dt.timestamp()); tz = date.decode().split()[-1]
    msg = subj + b'\n' + (b'\n' + body.rstrip(b'\n') + b'\n' if body else b'')
    files = []
    for fm in re.finditer(rb'diff --git a/(\S+) b/(\S+)\n(.*?)(?=\ndiff --git |\n-- \n)', rest, re.S):
