        im = re.search(rb'index ([0-9a-f]+)\.\.([0-9a-f]+)', fbody)
        pre_abbrev, post_abbrev = im.group(1).decode(), im.group(2).decode()
        hunks = []
        for hm in re.finditer(rb'@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@[^\n]*\n(.*?)(?=\n@@ |\Z)', fbody, re.S):
            hunks.append((int(hm.group(1)), int(hm.group(2) or 1), int(hm.group(3)), int(hm.group(4) or 1), hm.group(5).split(b'\n')))
