    patches[name] = dict(cid=cid.decode(), author=author.decode(), ts=ts, tz=tz, msg=msg, files=files)
    print(name, cid.decode(), author.decode(), ts, tz, repr(subj), [f[:3] for f in files])
# build blobs
newobjs = {}
for name in ('0001','0002','0003'):
    for path, pre, post, hunks in patches[name]['files']:
        if pre == '0000000':
            content = apply_patch(b'', hunks)
        else:
            content = apply_patch(blob(full(pre)), hunks)
        h = sha('blob', content)
        print(f"  {path}: built blob {h} expected prefix {post} match={h.startswith(post)} len={len(content)}")
        assert h.startswith(post)
        newobjs[h] = ('blob', content)
        patches[name].setdefault('blobs', {})[path] = h
